class ManagedResource:
    def __init__(self, name):
        self.name = name
        self.handle = None

    def __enter__(self):
        print(f"Открываем {self.name}")
        self.handle = acquire_resource(self.name)
        return self.handle  # значение для `as`

    def __exit__(self, exc_type, exc_val, exc_tb):
        print(f"Закрываем {self.name}")
        release_resource(self.handle)

from contextlib import contextmanager

@contextmanager
def open_file(path, mode="r"):
    f = open(path, mode)
    try:
        yield f  # значение для `as`
    finally:
        f.close()

with open_file("data.txt") as f:
    content = f.read()

@contextmanager
def transaction(db):
    try:
        yield db
        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()

with transaction(db) as tx:
    tx.execute("INSERT ...")

